<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; class Customer extends Model {protected $fillable=['type','name','contact_name','phone','email','address','tax_number','customer_code','is_active','payment_terms','credit_limit','city','country','notes']; protected $casts=['is_active'=>'boolean','credit_limit'=>'decimal:2']; public function orders():HasMany{return $this->hasMany(SalesOrder::class);} public function payments():HasMany{return $this->hasMany(Payment::class);} public function documents():HasMany{return $this->hasMany(CommercialDocument::class);}}
